args.code:
const list = await api.get('/mails', { customer_id: 'C005' });
if (!list || !Array.isArray(list) || list.length === 0) { return '메일을 찾을 수 없습니다.'; }
const first = list[0];
const mail = await api.get(`/mails/${first.id}`);
return mail.title || '제목이 없습니다.';

